+    fn right_widget(&self, right_content: &str) -> Paragraph<'static> {
+        let title = match self.windows[self.active_window].surface {
+            UiSurface::WorkLeafCommand => "command",
+            UiSurface::AgentChat => "chat",
+        };
+        let lines = pane_lines(right_content);
+        let spans = lines
+            .iter()
+            .enumerate()
+            .map(|(row, line)| self.visual_spans_for_line(PaneFocus::Right, row, line))
+            .collect::<Vec<_>>();
+        Paragraph::new(spans)
+            .block(Block::default().title(title).borders(Borders::ALL))
+            .wrap(Wrap { trim: false })
+    }
+
+    fn visual_spans_for_line(
+        &self,
+        focus: PaneFocus,
+        row: usize,
+        line: &str,
+    ) -> Spans<'static> {
+        let Some((start, end)) = self.visual_selected_columns(focus, row, line) else {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        };
+        styled_selection_spans(line, start, end)
+    }
+
+    fn visual_selected_columns(
+        &self,
+        focus: PaneFocus,
+        row: usize,
+        line: &str,
+    ) -> Option<(usize, usize)> {
+        let selection = self.visual_selection?;
+        if selection.focus != focus {
+            return None;
+        }
+        selected_columns(selection, row, line)
+    }
+
+    fn handle_visual_key(
+        &mut self,
+        key: UiKey,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.clear_visual_selection();
+            }
+            UiKey::Char('v') => {
+                self.toggle_visual_selection(
+                    VisualSelectionKind::Character,
+                    right_content,
+                    right_cursor_column,
+                );
+            }
+            UiKey::Char('V') => {
+                self.toggle_visual_selection(
+                    VisualSelectionKind::Line,
+                    right_content,
+                    right_cursor_column,
+                );
+            }
+            UiKey::Char('\u{16}') => {
+                self.toggle_visual_selection(
+                    VisualSelectionKind::Block,
+                    right_content,
+                    right_cursor_column,
+                );
+            }
+            UiKey::Char('y') => {
+                self.copy_visual_selection(right_content, false);
+                self.clear_visual_selection();
+            }
+            UiKey::Char('Y') => {
+                self.copy_visual_selection(right_content, true);
+                self.clear_visual_selection();
+            }
+            UiKey::Char('h') | UiKey::Left => self.move_visual_cursor(0, -1, right_content),
+            UiKey::Char('j') | UiKey::Down => self.move_visual_cursor(1, 0, right_content),
+            UiKey::Char('k') | UiKey::Up => self.move_visual_cursor(-1, 0, right_content),
+            UiKey::Char('l') | UiKey::Right => self.move_visual_cursor(0, 1, right_content),
+            UiKey::MouseClick { .. }
+            | UiKey::MouseScrollUp { .. }
+            | UiKey::MouseScrollDown { .. } => self.clear_visual_selection(),
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn start_visual_selection(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        let point = self.visual_start_point(right_content, right_cursor_column);
+        self.visual_selection = Some(VisualSelection {
+            focus: self.focus,
+            kind,
+            anchor: point,
+            cursor: point,
+        });
+        self.mode = UiMode::Command;
+    }
+
+    fn toggle_visual_selection(
+        &mut self,
+        kind: VisualSelectionKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        if self
+            .visual_selection
+            .is_some_and(|selection| selection.kind == kind)
+        {
+            self.clear_visual_selection();
+        } else if let Some(mut selection) = self.visual_selection {
+            selection.kind = kind;
+            self.visual_selection = Some(selection);
+        } else {
+            self.start_visual_selection(kind, right_content, right_cursor_column);
+        }
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn visual_start_point(
+        &self,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> TextPoint {
+        let lines = self.pane_text_lines(self.focus, right_content);
+        let row = match self.focus {
+            PaneFocus::Left => self.control_selected,
+            PaneFocus::Right => lines.len().saturating_sub(1),
+        }
+        .min(lines.len().saturating_sub(1));
+        let column = match self.focus {
+            PaneFocus::Left => 0,
+            PaneFocus::Right => right_cursor_column.unwrap_or(0),
+        };
+        clamp_text_point(TextPoint { row, column }, &lines)
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize, right_content: &str) {
+        let Some(mut selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.pane_text_lines(selection.focus, right_content);
+        let max_row = lines.len().saturating_sub(1);
+        let next_row = selection
+            .cursor
+            .row
+            .saturating_add_signed(row_delta)
+            .min(max_row);
+        let next_column = selection.cursor.column.saturating_add_signed(column_delta);
+        selection.cursor = clamp_text_point(
+            TextPoint {
+                row: next_row,
+                column: next_column,
+            },
+            &lines,
+        );
+        self.visual_selection = Some(selection);
+    }
+
+    fn pane_text_lines(&self, focus: PaneFocus, right_content: &str) -> Vec<String> {
+        match focus {
+            PaneFocus::Left => {
+                let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+                self.left_pane_widget_lines(inner_width)
+                    .into_iter()
+                    .map(|line| line.text)
+                    .collect()
+            }
+            PaneFocus::Right => pane_lines(&self.visible_right_content(right_content)),
+        }
+    }
+
+    fn copy_visual_selection(&mut self, right_content: &str, force_linewise: bool) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.pane_text_lines(selection.focus, right_content);
+        let text = selected_text(selection, &lines, force_linewise);
+        self.copy_text_to_clipboard(text);
+    }
+
+    fn copy_current_line(&mut self, right_content: &str, right_cursor_column: Option<usize>) {
+        let focus = self.focus;
+        let lines = self.pane_text_lines(focus, right_content);
+        let point = self.visual_start_point(right_content, right_cursor_column);
+        let text = lines
+            .get(point.row)
+            .map(|line| format!("{line}\n"))
+            .unwrap_or_default();
+        self.copy_text_to_clipboard(text);
+    }
+
+    fn copy_text_to_clipboard(&mut self, text: String) {
+        let copied_chars = text.chars().count();
+        *self.pending_clipboard.borrow_mut() = Some(text);
+        self.show_status_notice(
+            format!("copied {copied_chars} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn visual_cursor_screen_position(&self, selection: VisualSelection) -> (u16, u16) {
+        let layout = self.layout();
+        let row = selection.cursor.row.saturating_add(2);
+        let column = match selection.focus {
+            PaneFocus::Left => selection.cursor.column.saturating_add(2),
+            PaneFocus::Right => usize::from(layout.left_width)
+                .saturating_add(2)
+                .saturating_add(selection.cursor.column),
+        };
+        (
+            row.min(usize::from(u16::MAX)) as u16,
+            column.min(usize::from(u16::MAX)) as u16,
+        )
+    }
